#!/usr/bin/env node

import { google } from 'googleapis';
import { readFileSync } from 'fs';

const CREDENTIALS_PATH = '/root/auth/calendar/credentials.json';
const TOKENS_PATH = '/root/auth/calendar/tokens.json';

const credentials = JSON.parse(readFileSync(CREDENTIALS_PATH, 'utf8'));
const tokenConfig = JSON.parse(readFileSync(TOKENS_PATH, 'utf8'));
const tokens = tokenConfig.accounts.default;

const { client_id, client_secret } = credentials.installed;
const oauth2Client = new google.auth.OAuth2(client_id, client_secret);
oauth2Client.setCredentials(tokens);

const calendar = google.calendar({ version: 'v3', auth: oauth2Client });

// Query events for Jan 6-9, 2026
const timeMin = '2026-01-06T00:00:00-08:00';
const timeMax = '2026-01-09T23:59:59-08:00';

try {
  const res = await calendar.events.list({
    calendarId: 'primary',
    timeMin,
    timeMax,
    singleEvents: true,
    orderBy: 'startTime',
  });

  const events = res.data.items || [];
  console.log(JSON.stringify(events, null, 2));
} catch (err) {
  console.error('Error fetching calendar events:', err.message);
  process.exit(1);
}

