import { google } from 'googleapis';
import { readFileSync } from 'fs';

const CREDENTIALS_PATH = '/root/auth/gmail/credentials.json';
const TOKENS_PATH = '/root/auth/gmail/tokens.json';

const credentials = JSON.parse(readFileSync(CREDENTIALS_PATH, 'utf8'));
const tokenConfig = JSON.parse(readFileSync(TOKENS_PATH, 'utf8'));
const tokens = tokenConfig.accounts.default;

const { client_id, client_secret } = credentials.installed;
const oauth2Client = new google.auth.OAuth2(client_id, client_secret);
oauth2Client.setCredentials({
  access_token: tokens.access_token,
  refresh_token: tokens.refresh_token,
  token_type: 'Bearer',
  expiry_date: tokens.expiry_date
});

const gmail = google.gmail({ version: 'v1', auth: oauth2Client });

// Get command line arguments
const args = process.argv.slice(2);
const to = args[0];
const subject = args[1];
const body = args[2];

if (!to || !subject || !body) {
  console.error('Usage: node send-meeting-reply.js <to> <subject> <body>');
  process.exit(1);
}

// Create email
const headers = [
  `To: ${to}`,
  `Subject: ${subject}`,
  'Content-Type: text/plain; charset=utf-8',
  '',
  body
].join('\r\n');

const encodedMessage = Buffer.from(headers)
  .toString('base64')
  .replace(/\+/g, '-')
  .replace(/\//g, '_')
  .replace(/=+$/, '');

try {
  const result = await gmail.users.messages.send({
    userId: 'me',
    requestBody: {
      raw: encodedMessage
    }
  });
  console.log(JSON.stringify({ success: true, messageId: result.data.id, threadId: result.data.threadId }));
} catch (err) {
  console.error(JSON.stringify({ success: false, error: err.message, code: err.code, details: err.errors }));
  process.exit(1);
}

