    scope: 'https://www.googleapis.com/auth/gmail.send https://www.googleapis.com/auth/gmail.modify',
    aud: 'https://oauth2.googleapis.com/token',
    iat: now,
    exp: now + 3600
  };

  const header = Buffer.from(JSON.stringify({alg: 'RS256', typ: 'JWT'})).toString('base64url');
  const payload = Buffer.from(JSON.stringify(claim)).toString('base64url');
  const unsignedJwt = header + '.' + payload;

  const sign = crypto.createSign('RSA-SHA256');
  sign.update(unsignedJwt);
  const signature = sign.sign(keyFile.private_key, 'base64url');
  const signedJwt = unsignedJwt + '.' + signature;

  const tokenRes = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: 'grant_type=urn%3Aietf%3Aparams%3Aoauth%3Agrant-type%3Ajwt-bearer&assertion=' + signedJwt
  });

  const tokenData = await tokenRes.json();
  console.log('Token exchange:', JSON.stringify(tokenData));

  if (tokenData.access_token) {
    // Try Gmail API
    const profileRes = await fetch('https://www.googleapis.com/gmail/v1/users/me/profile', {
      headers: { 'Authorization': 'Bearer ' + tokenData.access_token }
    });
    const profileData = await profileRes.json();
    console.log('Gmail profile:', JSON.stringify(profileData));

    // Try sending
    const body = 'To: test@test.com\r\nSubject: Test\r\nContent-Type: text/plain\r\n\r\nTest';
    const raw = Buffer.from(body).toString('base64url');
    const sendRes = await fetch('https://www.googleapis.com/gmail/v1/users/me/messages/send', {
      method: 'POST',
      headers: { 
        'Authorization': 'Bearer ' + tokenData.access_token,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ raw })
    });
    const sendData = await sendRes.json();
    console.log('Send result:', JSON.stringify(sendData));
  }
}

